/* Therapeutics Exam 3: contraceptives (PHAR 451 Contraception Days 1 to 3 and the menstrual cycle warm-up worksheet) */
const CT = (t, d, q, a, w, e, s) => Q("TH3C", d, q, a, w, e, t, s);
const CTD1 = "Contraception Day 1 lecture", CTD2 = "Contraception Day 2 lecture", CTD3 = "Contraception Day 3 lecture", CTW = "Menstrual cycle warm-up worksheet";
/* draw-the-line questions: the card shows a blank cycle graph (cycle.js) and the player draws the hormone */
const CTDRAW = (h, d, q, a, w, e, s) => { CT("Cycle: draw the hormone", d, q, a, w, e, s); BANK[BANK.length - 1].draw = h; };

/* ---------- Cycle physiology ---------- */
CTDRAW("LH", 2, "Draw the line for LH across the 28-day cycle. Press and drag from day 1 to day 28.", "LH: low baseline with one sharp spike at day 14", ["LH: slow rise to a broad peak at day 21", "LH: high in days 1 to 5 and falling all cycle", "LH: steady high level through the whole cycle"], "LH stays low, then surges just before day 14. The surge triggers ovulation and then LH falls back to baseline.", CTW + ", Part 1 graph; " + CTD1 + ", slide 3");
CTDRAW("FSH", 3, "Draw the line for FSH across the 28-day cycle. Press and drag from day 1 to day 28.", "FSH: higher early in the cycle, a small bump at day 14, then low in the luteal phase", ["FSH: one sharp spike at day 14 and flat elsewhere", "FSH: rises steadily to a peak at day 21", "FSH: flat at the same level all cycle"], "FSH is highest early to recruit follicles, falls as estradiol and inhibin rise, has a small bump with the LH surge, then stays low in the luteal phase and rises again near the end.", CTW + ", Part 1 graph; " + CTD1 + ", slide 3");
CTDRAW("E2", 3, "Draw the line for estradiol across the 28-day cycle. Press and drag from day 1 to day 28.", "Estradiol: peaks around day 12, dips near day 14, then a smaller second hump in the luteal phase", ["Estradiol: flat until day 14, then one big peak at day 21", "Estradiol: sharp spike at day 14 only", "Estradiol: high on day 1 and falling steadily"], "Growing follicles make rising estradiol that peaks just before ovulation. It dips, then the corpus luteum makes a smaller second rise before everything falls near day 28.", CTW + ", Part 1 graph; " + CTD1 + ", slide 17");
CTDRAW("P4", 3, "Draw the line for progesterone across the 28-day cycle. Press and drag from day 1 to day 28.", "Progesterone: near zero until ovulation, peaks around day 21, then falls by day 28", ["Progesterone: peaks at day 12 and is low in the luteal phase", "Progesterone: sharp spike at day 14 only", "Progesterone: high early and falling all cycle"], "Progesterone is low before ovulation. After ovulation the corpus luteum makes it, it peaks mid-luteal, and the fall near day 28 triggers menses.", CTW + ", Part 1 graph; " + CTD1 + ", slide 17");
CT("Cycle: physiology", 1, "In the follicular phase, what do rising estradiol and inhibin do to FSH secretion?", "Decrease it", ["Increase it", "Have no effect on it", "Trigger an FSH surge"], "Estradiol and inhibin are negative feedback on FSH, so FSH falls as the follicle matures.", CTW + ", Part 2, question 1");
CT("Cycle: physiology", 1, "Which hormone surge directly triggers ovulation?", "LH", ["FSH", "Progesterone", "hCG"], "The LH surge around day 14 triggers release of the egg.", CTW + ", Part 2, question 2");
CT("Cycle: physiology", 1, "Which hormone makes cervical mucus thick and scant, so it acts as a barrier to sperm?", "Progesterone", ["Estradiol, which makes the mucus thin and stretchy", "FSH", "LH"], "Progesterone thickens mucus. This is also why progestin-only methods work, in part.", CTW + ", Part 2, question 3");
CT("Cycle: physiology", 1, "In a cycle without pregnancy, what triggers menses?", "Falling progesterone", ["Rising LH", "Rising estradiol late in the luteal phase", "Rising hCG"], "The corpus luteum fades, progesterone falls, and the lining sheds.", CTW + ", Part 2, question 4");
CT("Cycle: physiology", 2, "Which best describes the fertile window?", "The 6 days ending on ovulation day", ["The 6 days starting on ovulation day", "Days 1 to 6 of the cycle", "The 6 days before menses"], "Sperm can survive for days, so intercourse in the days before ovulation can cause pregnancy.", CTW + ", Part 2, question 5");
CT("Cycle: physiology", 1, "Which pituitary hormone mainly drives follicle growth early in the cycle?", "FSH", ["LH", "Progesterone", "Inhibin"], "FSH recruits and grows follicles. The ovarian hormones are estradiol and progesterone.", CTD1 + ", slides 3, 17, 18");
CT("Cycle: physiology", 2, "Which hormone, made mainly by the corpus luteum, peaks in the luteal phase?", "Progesterone", ["FSH, which peaks just before ovulation", "LH", "hCG"], "After ovulation the empty follicle becomes the corpus luteum, which makes progesterone (and some estradiol).", CTW + ", Part 1 graph");

/* ---------- Overview of methods ---------- */
CT("Methods: overview", 1, "About what proportion of US pregnancies were unintended in 2019?", "42%", ["25%", "33%", "56%"], "About 60% of people with an unintended pregnancy reported not using any contraception.", CTD1 + ", slides 4, 5");
CT("Methods: overview", 1, "Which method is a LARC?", "Etonogestrel implant", ["Vaginal ring", "Depo-Provera injection", "Contraceptive patch"], "LARCs are the IUDs (copper or levonorgestrel) and the implant.", CTD1 + ", slide 10");
CT("Methods: overview", 1, "Which of these is a nonhormonal method?", "Copper IUD", ["Mirena", "Nexplanon", "Depo-Provera"], "Nonhormonal methods are fertility awareness, barrier methods and the copper IUD.", CTD1 + ", slide 10");
CT("Methods: overview", 1, "Which of these is a combined hormonal contraceptive (CHC)?", "Intravaginal ring", ["Nexplanon implant", "Depo-Provera injection", "Mirena IUD"], "CHCs are the combined pill, patch and ring. The implant, injection, IUD and mini pill are progestin only.", CTD1 + ", slide 10");
CT("Methods: overview", 2, "Which method has the lowest typical-use pregnancy rate in the first year?", "Implant (0.1%)", ["Injectable (4%)", "Combined pill (7%)", "Male condom (13%)"], "Typical-use rates are under 1% for the implant, IUDs and sterilization, about 4 to 7% for the injection, pill, patch and ring, and 13% or more for condoms and other barriers.", CTD1 + ", slide 9");
CT("Methods: overview", 2, "About what percent of women become pregnant in the first year of typical use of the combined pill, patch or ring?", "7%", ["0.3%", "13%", "21%"], "Perfect use is 0.3%. The gap is mostly missed doses and late changes.", CTD1 + ", slide 9");
CT("Methods: overview", 1, "What is the typical-use first-year pregnancy rate with no method at all?", "85%", ["42%", "56%", "25%"], "This is the baseline all methods are compared against.", CTD1 + ", slide 9");
CT("Methods: overview", 2, "Which is a disadvantage of fertility awareness-based methods?", "Relatively high pregnancy rates and no STI protection", ["Requires a prescription and a clinic visit for fitting", "Causes irregular bleeding in most users", "Raises the risk of blood clots"], "They avoid intercourse around the fertile days, which is hard to time perfectly.", CTD1 + ", slide 12");
CT("Methods: barrier", 2, "How long must the Today sponge stay in place after intercourse?", "At least 6 hours (up to 24 hours total)", ["30 minutes", "2 hours", "48 hours after intercourse, with no maximum time"], "The sponge contains nonoxynol-9 and can be inserted up to 6 hours before intercourse.", CTD1 + ", slide 15");
CT("Methods: barrier", 2, "Which barrier method must be fitted and needs a prescription?", "Diaphragm", ["Today sponge", "Spermicidal foam", "Internal (female) condom"], "The diaphragm is a dome-shaped cap that covers the cervix and can be used with spermicide.", CTD1 + ", slide 15");
CT("Methods: barrier", 2, "Which spermicide product is prescription only?", "Phexxi", ["Today sponge", "Nonoxynol-9 foam", "Male condom"], "Most spermicides are OTC. Phexxi is the Rx vaginal option.", CTD1 + ", slide 15");

/* ---------- Mechanism of action ---------- */
CT("Mechanism of action", 2, "In a combined hormonal contraceptive, which hormone's secretion does the estrogen mainly suppress, limiting follicle selection?", "FSH", ["Progesterone", "hCG", "Prolactin"], "Estrogen suppresses FSH (partly, depending on dose). The progestin blocks the LH surge.", CTD1 + ", slide 18");
CT("Mechanism of action", 2, "Which event do progestins block to prevent ovulation?", "The LH surge", ["FSH release early in the cycle", "Implantation only", "Sperm production"], "Progestins block the LH surge, so ovulation does not happen. They also thicken cervical mucus.", CTD1 + ", slide 18");
CT("Mechanism of action", 2, "Which effect do all progestin methods share?", "Thickened cervical mucus that blocks sperm", ["Copper release", "A larger LH surge at mid-cycle", "A thicker uterine lining"], "Progestins also thin the endometrium and slow tubal motility.", CTD1 + ", slide 18");
CT("Mechanism of action", 2, "How does the copper IUD mainly prevent pregnancy?", "It impairs sperm motility and viability and causes local inflammation", ["It blocks the LH surge", "It thickens cervical mucus with a small dose of progestin", "It suppresses FSH"], "The copper IUD is hormone free, so it does not suppress ovulation.", CTD1 + ", slides 18, 32");
CT("Mechanism of action", 2, "In combined contraceptives, which hormone stabilizes the endometrium to give better cycle control?", "Estrogen", ["Progestin", "Androgen", "FSH"], "Progestin thins the lining. Estrogen stabilizes it, which helps reduce breakthrough bleeding.", CTD1 + ", slide 18");
CT("Mechanism of action", 3, "How does an LNG IUD act?", "Mostly local effects in the uterus, with little systemic hormone", ["Mostly systemic effects, like a pill", "By releasing copper ions", "By blocking only the LH surge, like the pill does"], "It thins the endometrium, thickens mucus and slows tubal motility. It is not a systemic method like the ring.", CTD1 + ", slides 20, 32, 35");

/* ---------- Estrogens and progestins ---------- */
CT("Hormones: estrogens", 1, "Which estrogen is the most common in hormonal contraceptives?", "Ethinyl estradiol", ["Estetrol", "Mestranol", "Estradiol valerate"], "EE is the most common. Its ethinyl group blocks breakdown, which adds stability.", CTD1 + ", slide 19");
CT("Hormones: estrogens", 2, "Which estrogen is a prodrug that is converted to ethinyl estradiol?", "Mestranol", ["Estetrol", "Estradiol valerate", "Estradiol cypionate"], "Mestranol is metabolized to EE.", CTD1 + ", slide 19");
CT("Hormones: estrogens", 2, "Which estrogen is the native fetal estrogen used in Nextstellis?", "Estetrol", ["Mestranol", "Estradiol valerate", "Ethinyl estradiol"], "Estetrol has a half-life of about 27 hours.", CTD1 + ", slides 15, 19");
CT("Hormones: estrogens", 3, "How is estetrol mainly cleared?", "Glucuronidation (UGT2B7), not CYP3A4", ["CYP3A4 oxidation", "CYP2C19", "Unchanged in the urine with no liver metabolism"], "Ethinyl estradiol has extensive first-pass metabolism by CYP3A4 and conjugation, with oral bioavailability of about 43%.", CTD1 + ", slide 19");
CT("Hormones: estrogens", 3, "Why could estrogen doses in combined pills be lowered over time?", "Newer progestins suppress ovulation better, so less EE is needed", ["EE became more potent", "Estrogen is no longer needed for any cycle control at all", "Progestins stopped being absorbed"], "Progestins with more antigonadotrophic activity allow effective ovulation suppression at lower EE doses.", CTD1 + ", slide 19");
CT("Hormones: estrogens", 2, "Which estrogen has the more favorable aquatic ecotoxicity profile?", "Estetrol", ["Ethinyl estradiol", "Estradiol", "Mestranol"], "Estetrol is plant-derived, less is excreted in urine, and it breaks down faster.", CTD1 + ", slide 20");
CT("Hormones: estrogens", 2, "Which brand combines estradiol valerate with dienogest in four phases?", "Natazia", ["Kariva", "Yaz", "Nextstellis"], "Natazia is the quadriphasic product.", CTD2 + ", slide 16");
CT("Hormones: progestins", 2, "Which progestin has the highest androgenic activity?", "Levonorgestrel", ["Norgestimate, a third-generation progestin", "Drospirenone", "Dienogest"], "Levonorgestrel is rated four plus for androgenic activity. Drospirenone and dienogest have none.", CTD1 + ", slide 22");
CT("Hormones: progestins", 2, "Which progestin has anti-androgen and anti-mineralocorticoid activity?", "Drospirenone", ["Levonorgestrel", "Norethindrone", "Desogestrel"], "That is why drospirenone can help acne and hirsutism and has a mild diuretic effect.", CTD1 + ", slides 22, 23");
CT("Hormones: progestins", 2, "Levonorgestrel and norgestrel belong to which progestin generation?", "Second", ["First", "Third", "Fourth"], "First generation is the norethindrones. Third is norgestimate and desogestrel.", CTD1 + ", slide 21");
CT("Hormones: progestins", 2, "Norgestimate and desogestrel belong to which progestin generation?", "Third", ["First", "Second", "Fourth"], "Norethindrone is first generation. Levonorgestrel is second.", CTD1 + ", slide 21");
CT("Hormones: progestins", 3, "A patient takes a drospirenone pill and starts an ACE inhibitor. What should be monitored?", "Potassium", ["Calcium", "Sodium only", "Magnesium"], "Drospirenone 3 to 4 mg has an anti-mineralocorticoid effect similar to spironolactone 25 mg. The risk rises with ACE inhibitors, ARBs, potassium-sparing diuretics and strong CYP3A4 inhibitors.", CTD1 + ", slide 23");

/* ---------- LARCs ---------- */
CT("LARC: IUDs", 2, "Which two LNG IUDs contain 52 mg of levonorgestrel?", "Mirena and Liletta", ["Kyleena and Skyla", "Mirena and Kyleena", "Liletta and Skyla"], "Both are approved for 8 years. Kyleena has 19.5 mg (5 years) and Skyla has 13.5 mg (3 years).", CTD1 + ", slide 27");
CT("LARC: IUDs", 2, "Which LNG IUD has the lowest dose and the shortest approved duration?", "Skyla (13.5 mg, 3 years)", ["Kyleena (19.5 mg, 5 years)", "Mirena (52 mg, 8 years)", "Liletta (52 mg, 8 years)"], "Higher hormone content means longer duration and a greater chance of amenorrhea.", CTD1 + ", slides 27, 33, 35");
CT("LARC: IUDs", 2, "A patient wants the LNG IUD most likely to cause amenorrhea. Which fits best?", "Mirena", ["Skyla", "Kyleena", "Paragard"], "Amenorrhea at 5 years is about 40% with Mirena and Liletta, 23% with Kyleena and 12% with Skyla at 3 years. Paragard is copper.", CTD1 + ", slides 33, 35");
CT("LARC: IUDs", 2, "Which IUD may suit a patient with a smaller uterus or who has not given birth?", "Kyleena", ["Mirena", "Liletta", "Paragard"], "Kyleena has a smaller size.", CTD1 + ", slide 27");
CT("LARC: IUDs", 2, "How long is Paragard FDA approved for?", "10 years", ["3 years", "5 years, the same as Skyla and Kyleena", "8 years"], "Data support use for up to 12 years. Miudella, a newer copper IUD, was approved for 3 years.", CTD1 + ", slides 27, 28");
CT("LARC: IUDs", 2, "Which method is best for a patient who needs highly effective contraception that is hormone free, such as after breast cancer?", "Copper IUD", ["LNG IUD", "Nexplanon implant", "Depo-Provera"], "Current breast cancer is MEC 4 for all hormonal methods but MEC 1 for the copper IUD.", CTD1 + ", slide 27; " + CTD2 + ", slide 31");
CT("LARC: IUDs", 2, "Which IUD should usually be avoided in a patient with heavy periods and dysmenorrhea?", "Copper IUD", ["LNG IUD that releases 52 mg of levonorgestrel", "Skyla", "Kyleena"], "The copper IUD can increase bleeding and cramping. LNG IUDs usually decrease bleeding and pain.", CTD1 + ", slide 27; " + CTD3 + ", slide 6");
CT("LARC: IUDs", 2, "A 34-year-old has heavy periods and iron-deficiency anemia and wants pregnancy prevention without a daily pill. Which is best?", "LNG IUD (Mirena)", ["Copper IUD (Paragard)", "Norethindrone mini pill", "Today sponge"], "LNG IUDs significantly decrease menstrual bleeding. The copper IUD can increase it, and a pill is daily.", CTD1 + ", slide 27; " + CTD2 + ", slide 27");
CT("LARC: IUDs", 3, "What is the usual time of IUD expulsion?", "The first 3 months after insertion", ["After about 5 years", "Only during menses after the second year of use", "Immediately at insertion only"], "Expulsion is uncommon, under 5%. A new IUD can be placed.", CTD1 + ", slide 34");
CT("LARC: IUDs", 3, "When is PID risk increased with an IUD?", "In the first 20 days after insertion", ["Throughout the whole time it is in place", "Only after year 5", "Only with LNG IUDs"], "Over the long term the risk is comparable to people without an IUD.", CTD1 + ", slide 34");
CT("LARC: IUDs", 2, "If a pregnancy occurs with an IUD in place, what is more likely compared with other pregnancies?", "It is more commonly ectopic", ["It is always ectopic and needs surgery at once", "It is never ectopic", "It is always twins"], "The absolute risk of ectopic pregnancy is not higher than in non-users, but when pregnancy occurs 15 to 50% are ectopic.", CTD1 + ", slide 34");
CT("LARC: IUDs", 2, "Which drug can reduce IUD insertion pain?", "Lidocaine (paracervical block or topical)", ["Misoprostol", "Ulipristal given by mouth 30 minutes before insertion", "Metformin"], "Misoprostol is not recommended routinely (CDC SPR 2024).", CTD1 + ", slide 35");
CT("LARC: implant", 1, "What does the Nexplanon implant contain?", "Etonogestrel", ["Levonorgestrel", "Medroxyprogesterone", "Norethindrone"], "It is a subdermal rod placed in the upper arm. FDA-approved duration is up to 5 years (January 2026).", CTD1 + ", slides 27, 29");
CT("LARC: implant", 2, "What is the most common adverse effect of the implant?", "Irregular bleeding", ["Ectopic pregnancy", "Nausea and vomiting", "Hyperkalemia"], "More than 20% become amenorrheic with continued use, but many have prolonged bleeding or spotting.", CTD1 + ", slide 29");
CT("LARC: implant", 3, "What is new for Nexplanon in 2026?", "A REMS: only certified prescribers and pharmacies can obtain it", ["It became OTC", "Its approval was shortened to 1 year", "It was restricted to patients with a BMI under 25"], "Inserters complete training, and pharmacies may supply it only to certified providers.", CTD1 + ", slides 28, 29");
CT("LARC: implant", 3, "A patient with a Nexplanon implant reports chest pain, shortness of breath and coughing up blood. What is the response?", "Emergency evaluation for possible pulmonary migration", ["Reassure her", "Schedule a routine visit next month to check the implant", "Start a stimulant laxative"], "Pulmonary vascular migration is rare but serious.", CTD1 + ", slide 30");
CT("LARC: implant", 3, "A patient cannot feel her implant. What should be done?", "Prompt clinical evaluation and localization; do not attempt blind removal", ["Wait a few months to see if it returns on its own", "Remove it at home", "Assume she is protected"], "The patient also needs interim contraceptive advice if insertion is uncertain.", CTD1 + ", slide 30");
CT("LARC: implant", 3, "Which drugs can reduce the efficacy of the implant?", "CYP3A4 inducers", ["Broad-spectrum antibiotics", "Antacids", "Acetaminophen"], "Evaluate case by case. The package insert and CDC guidance differ.", CTD1 + ", slide 29");

/* ---------- Injectable, pills, ring, patch ---------- */
CT("Injectable: DMPA", 1, "How often is Depo-Provera given?", "Every 12 weeks", ["Every 4 weeks", "Every 6 months", "Once a year"], "It is given by deep IM injection or SQ. There is some flexibility, up to 14 weeks.", CTD2 + ", slide 5");
CT("Injectable: DMPA", 2, "Which hormonal method's efficacy is not reduced by higher BMI?", "DMPA injection", ["Combined patch", "Drospirenone and estetrol pill", "Plan B (levonorgestrel) emergency contraception"], "The patch may be less effective at 90 kg or more, and Nextstellis may be less effective at BMI 30 or more.", CTD2 + ", slides 5, 15, 22");
CT("Injectable: DMPA", 2, "DMPA should be avoided in which patient?", "One taking long-term corticosteroids", ["One with migraine without aura", "One using lamotrigine", "One who is breastfeeding"], "DMPA causes short-term bone loss. Avoid it with long-term corticosteroids or a history of high-risk fracture.", CTD2 + ", slide 6");
CT("Injectable: DMPA", 2, "Which is a common effect of DMPA after 12 months of use?", "More than half report amenorrhea", ["Heavier bleeding", "Improved bone density", "A rapid return to fertility after the last injection"], "Irregular bleeding is common in the first year. About 38% gain more than 10 lb over 24 months.", CTD2 + ", slide 6");
CT("Injectable: DMPA", 2, "Which method has the slowest return to fertility?", "DMPA", ["LNG IUD", "Implant", "Progestin-only pill"], "DMPA can delay fertility up to 12 months. LNG IUD, implant and POP return to fertility within one cycle.", CTD2 + ", slides 27, 35");
CT("Injectable: DMPA", 3, "What label update was added to Depo-Provera in December 2025?", "A meningioma warning", ["A stroke boxed warning", "A kidney injury warning", "A new weekly dose"], "Meningioma has been reported after repeated, mostly long-term use. Absolute risk is low.", CTD2 + ", slide 6");
CT("Progestin-only pills", 1, "Which progestin-only pill is sold OTC?", "Opill (norgestrel 0.075 mg)", ["Slynd (drospirenone 4 mg, with a 24 day active pack)", "Camila (norethindrone)", "Plan B"], "Opill was approved for OTC use in July 2023 with no age limit.", CTD2 + ", slides 7, 8");
CT("Progestin-only pills", 2, "A patient wants to buy Opill. Which patient should NOT use it?", "One who has had breast cancer", ["One who is breastfeeding", "One who takes ibuprofen", "One who is 17 years old and has no other conditions"], "Opill is also not for patients who are pregnant, already using another hormonal method, or who need emergency contraception.", CTD2 + ", slide 9");
CT("Progestin-only pills", 2, "A patient takes Opill more than 3 hours late. What should she do?", "Take it as soon as possible, then use backup for 48 hours", ["Skip it and double the next dose", "Nothing, no backup is needed", "Stop the pack and start a brand new one a week later"], "Norethindrone and norgestrel have short half-lives, so timing matters.", CTD2 + ", slide 9");
CT("Progestin-only pills", 2, "Opill may interact with which emergency contraceptive?", "Ulipristal (ella)", ["Levonorgestrel (Plan B)", "Copper IUD", "Condoms"], "Opill is not a morning-after pill.", CTD2 + ", slide 9");
CT("Progestin-only pills", 2, "Which POP contains drospirenone and may require monitoring for hyperkalemia?", "Slynd", ["Opill", "Camila", "Errin"], "Drospirenone has anti-androgenic benefits and is more forgiving of late doses than the other POPs.", CTD2 + ", slide 7");
CT("Progestin-only pills", 2, "Progestin-only pills are a good choice for which patient?", "One who cannot take estrogen", ["One who cannot take a daily pill at the same time", "One who wants the most forgiving daily schedule", "One who wants a predictable, regular bleeding pattern"], "POPs avoid estrogen. Avoid them if she cannot take one at the same time every day.", CTD2 + ", slides 7, 27");
CT("Combined pills", 2, "What is a good place to start for a new combined pill user with no compelling indication?", "A monophasic pill with a moderate dose of EE", ["A triphasic pill", "A quadriphasic pill", "A very high dose EE pill, such as 50 mcg"], "Multiphasic pills are not the best place to start.", CTD2 + ", slides 13, 16");
CT("Combined pills", 2, "A patient wants to skip placebo weeks and use a pill continuously. Which type should she use?", "A monophasic combined pill", ["A biphasic pill", "A triphasic pill", "A progestin-only pill taken without a break"], "Avoid multiphasic pills for continuous use.", CTD2 + ", slide 17");
CT("Combined pills", 2, "What is a downside of extended or continuous cycle regimens?", "More spotting in the first 3 to 6 months", ["Less effective ovulation suppression than cyclic dosing", "A higher failure rate", "Heavier withdrawal bleeds"], "Benefits include fewer periods and help with menstrual issues.", CTD2 + ", slide 17");
CT("Combined pills", 3, "Why can extended or continuous cycles help?", "They avoid the hormone-free interval, keeping FSH and LH suppressed", ["They raise FSH and LH to improve cycle control", "They remove the need for estrogen", "They lower LH only"], "They avoid the estrogen cliff and cut headaches, pelvic pain and breast tenderness.", CTD2 + ", slide 18");
CT("Combined pills", 2, "Which pill contains estetrol with drospirenone?", "Nextstellis", ["Yaz", "Natazia", "Seasonique, an extended cycle pill with levonorgestrel"], "It has 24 active days. The label says it may be less effective at BMI 30 or more.", CTD2 + ", slides 14, 15");
CT("Combined pills", 2, "Which pill is an 84-active-tablet extended-cycle product?", "Seasonique", ["Yaz", "Loestrin 24 Fe", "Nextstellis"], "Seasonique has 84 tablets of EE 0.03 mg with levonorgestrel 0.15 mg, plus 7 low-dose EE tablets.", CTD2 + ", slide 18");
CT("Combined pills", 2, "Which of these is quadriphasic?", "Natazia", ["Kariva", "Estrostep", "Yaz"], "Kariva is biphasic and Estrostep is triphasic.", CTD2 + ", slide 16");
CT("Ring and patch", 1, "What hormones are in NuvaRing?", "Ethinyl estradiol and etonogestrel", ["Estetrol and drospirenone", "Levonorgestrel only", "Ethinyl estradiol and norelgestromin"], "The ring is in for 21 days and out for 7, or replaced every 28 days for continuous use.", CTD2 + ", slide 19");
CT("Ring and patch", 2, "How long can one Annovera ring be used?", "Up to 1 year (13 cycles)", ["21 days", "3 months", "5 years if it is stored in the refrigerator"], "It is reusable and contains EE with segesterone. It should not be used for continuous regimens.", CTD2 + ", slides 17, 19");
CT("Ring and patch", 2, "What is the most common reason people stop using the ring?", "Foreign body sensation or other device-related issues", ["Weight gain", "Loss of bone density after long term use", "Hyperkalemia"], "Most patients and partners do not report discomfort during intercourse.", CTD2 + ", slide 21");
CT("Ring and patch", 2, "How is the contraceptive patch used?", "Change weekly for 3 weeks, then a patch-free week", ["Change daily", "Wear one patch continuously for a month without changing it", "Change every 3 days"], "For continuous use, replace every 7 days without a break.", CTD2 + ", slides 17, 22");
CT("Ring and patch", 2, "A patient with a BMI of 36 asks about the patch. What is the best answer?", "Avoid it: the Xulane label contraindicates BMI of 30 or more", ["Use it with a higher dose", "It is MEC 1", "Use it only during the luteal phase of her cycle"], "The patch may also be less effective at 90 kg or more. An IUD, implant or DMPA fits better.", CTD2 + ", slide 22; " + CTD3 + ", slide 3");
CT("Ring and patch", 3, "How does EE exposure from the patch compare with a 35 mcg EE pill?", "About 60% higher (AUC)", ["About 60% lower", "The same", "Twice as high in Cmax and the same in AUC"], "Nausea, breast tenderness and application-site reactions may be more common.", CTD2 + ", slide 22");
CT("Ring and patch", 2, "How does a vaginal ring differ from an LNG IUD in hormone exposure?", "The ring is absorbed into the bloodstream; the IUD acts mostly locally", ["The ring acts mostly locally", "Both act only locally", "Neither is absorbed"], "The ring gives systemic effects, which is why estrogen-related restrictions apply.", CTD2 + ", slide 20");

/* ---------- Choosing a method, MEC, interactions ---------- */
CT("Choosing a method", 2, "Which is the best choice for someone who cannot take a pill every day?", "An IUD, implant, DMPA, weekly patch or monthly ring", ["A progestin-only pill", "A daily combined pill with an alarm only", "Fertility awareness methods"], "Avoid the POP if she cannot take it at the same time every day.", CTD2 + ", slide 27");
CT("Choosing a method", 2, "A 43-year-old forgets her combined pill once or twice a month and wants no more children. What fits best?", "A long-acting method such as an IUD or implant", ["Switch to a progestin-only pill", "Take the pill with her morning coffee only", "Fertility awareness"], "If daily dosing is hard, choose a method that does not depend on daily dosing.", CTD2 + ", slides 27, 47");
CT("Choosing a method", 2, "How soon does fertility usually return after an LNG IUD, implant or POP?", "Within one cycle", ["About 2 months", "6 to 12 months", "More than a year"], "Combined pills take about 2 months, and DMPA can take up to 12 months.", CTD2 + ", slide 27");
CT("Choosing a method", 2, "Choice matters. In the study discussed, what happened to continuation when people got their method of choice?", "Far fewer stopped within 12 months", ["No difference", "More stopped within 12 months", "Only IUD users stayed"], "Only 8.9% of those who got their method of choice stopped within 12 months, compared with 72.2% of those who did not.", CTD2 + ", slide 26");
